from bioblend.galaxy import GalaxyInstance
import json
key=open('/run/secrets/galaxy_api_key').read().strip()
gi=GalaxyInstance(url='https://usegalaxy.org', key=key)
tc=gi.tools
tool_id='toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'
d=tc.show_tool(tool_id, io_details=True)
# print top-level inputs keys and relevant subtree
print('keys', list(d.keys()))
inputs=d.get('inputs',[])
def walk(x, indent=0):
 if isinstance(x, dict):
  if 'name' in x:
   print('  '*indent, x.get('name'), 'type=',x.get('type'), 'label=',x.get('label'))
  for k,v in x.items():
   if k in ('name','label','type','value','options'): pass
   else: walk(v, indent+1)
 elif isinstance(x, list):
  for y in x: walk(y, indent)
walk(inputs)
